import type {
  BallotTemplatePageInput,
  BallotTemplateTable,
  BallotTemplateRow,
  BBox,
  BallotTemplatePageOutput,
  SubmittedSignatureDetails,
  SubmittedSignatureStatus,
} from '~/client';
import type { TableModel, RowModel, RectModel } from '~/types/projects/labeling';

export function convertTablesToPageInput(
  tables: TableModel[],
  template_page_index: number,
  displaySize: { width: number; height: number },
  naturalSize: { width: number; height: number }
): BallotTemplatePageInput {
  // compute scale factors from display → original
  const scaleX = naturalSize.width / displaySize.width;
  const scaleY = naturalSize.height / displaySize.height;

  // pick the first table (or null)
  const tbl = tables.length > 0 ? tables[0] : null;

  // map the table itself
  const table: BallotTemplateTable | null = tbl
    ? {
        label: tbl.label,
        table_bbox: {
          left: Math.round(tbl.x * scaleX),
          top: Math.round(tbl.y * scaleY),
          right: Math.round((tbl.x + tbl.w) * scaleX),
          bottom: Math.round((tbl.y + tbl.h) * scaleY),
        },
      }
    : null;

  const rows: BallotTemplateRow[] | null = tbl
    ? tbl.rows
        .slice()
        .sort((a, b) => a.y - b.y)
        .map((row, idx) => {
          // display‐space absolute coords
          const dispRowX = tbl.x + row.x;
          const dispRowY = tbl.y + row.y;

          // signature (first one) if any
          const sig = row.sigs[0] ?? null;

          // convert to original coords
          const row_bbox: BBox = {
            left: Math.round(dispRowX * scaleX),
            top: Math.round(dispRowY * scaleY),
            right: Math.round((dispRowX + row.w) * scaleX),
            bottom: Math.round((dispRowY + row.h) * scaleY),
          };

          let sig_bbox: BBox | null = null;
          if (sig) {
            const dispSigX = dispRowX + sig.x;
            const dispSigY = dispRowY + sig.y;
            sig_bbox = {
              left: Math.round(dispSigX * scaleX),
              top: Math.round(dispSigY * scaleY),
              right: Math.round((dispSigX + sig.w) * scaleX),
              bottom: Math.round((dispSigY + sig.h) * scaleY),
            };
          }

          return {
            row_bbox,
            row_index: idx,
            row_label: row.label,
            sig_bbox,
            sig_label: sig?.label ?? null,
            row_crop_url: null,
          };
        })
    : null;

  return {
    template_page_index,
    table,
    rows,
  };
}

export function convertPageOutputToTableModels(
  page: BallotTemplatePageOutput,
  displaySize: { width: number; height: number },
  naturalSize: { width: number; height: number }
): TableModel[] {
  const { table: tblApi, rows: rowsApi } = page;
  if (!tblApi || !rowsApi) {
    return [];
  }

  const scaleX = displaySize.width / naturalSize.width;
  const scaleY = displaySize.height / naturalSize.height;

  const { left: tblLeft, top: tblTop, right: tblRight, bottom: tblBottom } = tblApi.table_bbox;

  const tableModel: TableModel = {
    id: `table_${page.template_page_index}`,
    x: tblLeft * scaleX,
    y: tblTop * scaleY,
    w: (tblRight - tblLeft) * scaleX,
    h: (tblBottom - tblTop) * scaleY,
    label: tblApi.label,
    rows: [],
  };

  const sortedRows = rowsApi.slice().sort((a, b) => a.row_index - b.row_index);

  sortedRows.forEach((rowApi) => {
    const { left: rowLeft, top: rowTop, right: rowRight, bottom: rowBottom } = rowApi.row_bbox;

    const relRowX = rowLeft - tblLeft;
    const relRowY = rowTop - tblTop;

    const rowModel: RowModel = {
      id: `row_${page.template_page_index}_${rowApi.row_index}`,
      x: relRowX * scaleX,
      y: relRowY * scaleY,
      w: (rowRight - rowLeft) * scaleX,
      h: (rowBottom - rowTop) * scaleY,
      label: rowApi.row_label,
      sigs: [],
    };

    if (rowApi.sig_bbox) {
      const { left: sigLeft, top: sigTop, right: sigRight, bottom: sigBottom } = rowApi.sig_bbox;
      const relSigX = sigLeft - rowLeft;
      const relSigY = sigTop - rowTop;

      const sigModel: RectModel = {
        id: `sig_${page.template_page_index}_${rowApi.row_index}`,
        x: relSigX * scaleX,
        y: relSigY * scaleY,
        w: (sigRight - sigLeft) * scaleX,
        h: (sigBottom - sigTop) * scaleY,
        label: rowApi.sig_label ?? '',
      };

      rowModel.sigs.push(sigModel);
    }

    tableModel.rows.push(rowModel);
  });

  return [tableModel];
}

export interface SubmittedSignatureModel extends RectModel {
  signatureId: string;
  type: SubmittedSignatureStatus;
}

export function convertSubmittedSignaturesToTableModels(
  signatures: SubmittedSignatureDetails[],
  displaySize: { width: number; height: number },
  naturalSize: { width: number; height: number }
): SubmittedSignatureModel[] {
  if (signatures.length === 0) {
    return [];
  }

  const scaleX = displaySize.width / naturalSize.width;
  const scaleY = displaySize.height / naturalSize.height;

  const sortedRows = signatures.slice().sort((a, b) => (a?.row_index || 0) - (b?.row_index || 0));

  const rowModels: SubmittedSignatureModel[] = [];

  sortedRows?.forEach((rowApi) => {
    if (!rowApi.row_box) return;
    const { left: rowLeft, top: rowTop, right: rowRight, bottom: rowBottom } = rowApi.row_box;

    const relRowX = rowLeft;
    const relRowY = rowTop;

    const rowModel: SubmittedSignatureModel = {
      id: `row_${rowApi.id}_${rowApi.row_index}`,
      x: relRowX * scaleX,
      y: relRowY * scaleY,
      w: (rowRight - rowLeft) * scaleX,
      h: (rowBottom - rowTop) * scaleY,
      label: '',
      signatureId: rowApi.id,
      type: rowApi.status,
    };
    rowModels.push(rowModel);
  });

  return rowModels;
}
